package scan

import (
	"fmt"
	"net/url"
	"strings"
)

// Building a Trivy invocation is pure: the same inputs produce the command that
// is run and the command that is shown. Keeping the two derived from one
// builder is what stops them drifting apart (§1.3 D19).

// containerScanPath is where a scanned directory is mounted inside the tool's
// container, so the argument passed to the tool is never the host path.
const containerScanPath = "/scan"

// dockerSocketMount lets a containerised Trivy inspect images held by the host
// daemon. It is a broad grant, so it is only made when there is no Trivy server
// to do the work instead.
const dockerSocketMount = "/var/run/docker.sock:/var/run/docker.sock:ro"

// serverAddr normalises the configured Trivy server address, refusing one Trivy
// cannot use.
//
// Trivy parses this as a URL and fails the entire scan when it cannot. A single
// stray ":" in the field — which is easy to get, since a bare ":" typed while
// the field has focus is a character rather than the command line (§3.7) —
// produces
//
//	FATAL flag error: unable to convert flags to options:
//	invalid server address format: parse ":": missing protocol scheme
//
// a message naming neither DevDesk nor the setting it came from. Worse, the
// field is persisted on every option toggle, so one keystroke breaks every
// later scan from every view until it is found in the config file.
//
// Surrounding space is not an address, so it trims to nothing and client-server
// mode is simply off. Anything else that is not an absolute URL is refused
// here, where the message can say where to fix it.
// ValidateTrivyServer reports whether a Trivy server address can be used, so a
// form can refuse it while the user is still looking at the field rather than
// letting the failure surface as a scan warning minutes later.
func ValidateTrivyServer(server string) error {
	_, err := serverAddr(server)
	return err
}

func serverAddr(server string) (string, error) {
	trimmed := strings.TrimSpace(server)
	if trimmed == "" {
		return "", nil
	}
	// Hostname() rather than Host: "http://:" parses with a Host of ":" and no
	// hostname at all, which is not somewhere a request can be sent.
	parsed, err := url.Parse(trimmed)
	if err != nil || parsed.Scheme == "" || parsed.Hostname() == "" {
		return "", fmt.Errorf(
			"trivy server address %q is not a URL (want http://host:port) — fix or clear scan.trivy_server", trimmed)
	}
	return trimmed, nil
}

// trivyArgs builds a vulnerability or license scan.
func trivyArgs(target string, targetType TargetType, licenseMode bool, tool ToolSpec,
	server string, ignoreUnfixed, ignoreEOL bool) (toolCmd, error) {
	server, err := serverAddr(server)
	if err != nil {
		return toolCmd{}, err
	}

	var args []string

	switch targetType {
	case TargetDirectory:
		args = []string{"fs", "--format", "json"}
		if licenseMode {
			args = append(args, "--scanners", "license")
		} else {
			args = append(args, "--scanners", "vuln")
		}
	case TargetImage:
		// --scanners vuln explicitly: Trivy's default for an image is
		// "vuln,secret", so this stage was running the secret scanner on every
		// image scan and throwing its output away. Secrets are the secret
		// stage's job, and asking for them twice would report each one twice.
		args = []string{"image", "--format", "json", "--scanners", "vuln"}
	default:
		return toolCmd{}, fmt.Errorf("unsupported target type: %s", targetType)
	}

	if server != "" {
		args = append(args, "--server", server)
	}
	if ignoreUnfixed {
		args = append(args, "--ignore-unfixed")
	}
	if ignoreEOL {
		args = append(args, "--ignore-status", "end_of_life")
	}

	return wrapTrivy(args, target, targetType, tool, server), nil
}

// trivySecretArgs builds a secret scan. Like misconfiguration, it reads content
// rather than a package manifest, so it applies to both target types — which is
// what gives an image scan a secret stage at all, Gitleaks being directory-only.
func trivySecretArgs(target string, targetType TargetType, tool ToolSpec, server string) (toolCmd, error) {
	server, err := serverAddr(server)
	if err != nil {
		return toolCmd{}, err
	}

	var args []string

	switch targetType {
	case TargetDirectory:
		args = []string{"fs", "--format", "json", "--scanners", "secret"}
	case TargetImage:
		args = []string{"image", "--format", "json", "--scanners", "secret"}
	default:
		return toolCmd{}, fmt.Errorf("unsupported target type: %s", targetType)
	}

	if server != "" {
		args = append(args, "--server", server)
	}

	// No --ignore-status: end_of_life describes a package's support window and
	// says nothing about a secret sitting in a file.
	return wrapTrivy(args, target, targetType, tool, server), nil
}

// trivyMisconfigArgs builds a misconfiguration scan. It reads configuration
// files rather than a package manifest, so it applies to both target types.
func trivyMisconfigArgs(target string, targetType TargetType, tool ToolSpec,

package scan

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"
)

// TrivyReport represents the JSON output from Trivy
type TrivyReport struct {
	Results []TrivyResult `json:"Results"`
}

// TrivyResult represents a single result from Trivy
type TrivyResult struct {
	Target            string                  `json:"Target"`
	Class             string                  `json:"Class"`
	Type              string                  `json:"Type"`
	Vulnerabilities   []TrivyVulnerability    `json:"Vulnerabilities"`
	Secrets           []TrivySecret           `json:"Secrets,omitempty"`
	Licenses          []TrivyLicense          `json:"Licenses,omitempty"`
	Misconfigurations []TrivyMisconfiguration `json:"Misconfigurations,omitempty"`
}

// TrivyVulnerability represents a vulnerability found by Trivy
type TrivyVulnerability struct {
	VulnerabilityID  string   `json:"VulnerabilityID"`
	PkgName          string   `json:"PkgName"`
	InstalledVersion string   `json:"InstalledVersion"`
	FixedVersion     string   `json:"FixedVersion"`
	Severity         string   `json:"Severity"`
	Title            string   `json:"Title"`
	Description      string   `json:"Description"`
	PrimaryURL       string   `json:"PrimaryURL,omitempty"`
	References       []string `json:"References,omitempty"`
}

// TrivySecret represents a secret found by Trivy
type TrivySecret struct {
	RuleID    string `json:"RuleID"`
	Category  string `json:"Category"`
	Severity  string `json:"Severity"`
	Title     string `json:"Title"`
	StartLine int    `json:"StartLine"`
	EndLine   int    `json:"EndLine"`
	Match     string `json:"Match"`
}

// TrivyLicense represents a license found by Trivy
type TrivyLicense struct {
	Severity   string  `json:"Severity"`
	Category   string  `json:"Category"` // forbidden, restricted, reciprocal, notice, permissive, unencumbered, unknown
	PkgName    string  `json:"PkgName"`
	FilePath   string  `json:"FilePath"`
	Name       string  `json:"Name"` // License identifier (SPDX): MIT, Apache-2.0, GPL-3.0, etc.
	Confidence float64 `json:"Confidence"`
	Link       string  `json:"Link"`
}

// TrivyMisconfiguration represents a misconfiguration found by Trivy
type TrivyMisconfiguration struct {
	Type          string `json:"Type"`
	ID            string `json:"ID"`
	AVDID         string `json:"AVDID"`
	Title         string `json:"Title"`
	Desc          string `json:"Description"`
	Message       string `json:"Message"`
	Severity      string `json:"Severity"`
	Resolution    string `json:"Resolution"`
	PrimaryURL    string `json:"PrimaryURL"`
	Status        string `json:"Status"`
	CauseMetadata struct {
		StartLine int `json:"StartLine"`
		EndLine   int `json:"EndLine"`
	} `json:"CauseMetadata"`
}

// RunTrivy executes Trivy and returns findings.
// progressFn is an optional callback called with each stderr line (DB download progress etc.).
func RunTrivy(ctx context.Context, target string, targetType TargetType, licenseMode bool, tool ToolSpec, server string, ignoreUnfixed bool, ignoreEOL bool, progressFn func(string)) ([]Finding, error) {
	tc, err := trivyArgs(target, targetType, licenseMode, tool, server, ignoreUnfixed, ignoreEOL)
	if err != nil {
		return nil, err
	}
	return runTrivy(ctx, tc, progressFn)
}

// runTrivy executes a built invocation and parses what it wrote to stdout.
//
// A non-zero exit is not on its own a failure: Trivy exits 1 when it finds
// vulnerabilities, and the report on stdout is exactly what the caller asked
// for. Only an exit that produced no report is reported as an error.
func runTrivy(ctx context.Context, tc toolCmd, progressFn func(string)) ([]Finding, error) {
	stdout, err := runner.Run(ctx, tc, progressFn)
	if err != nil {
		var exit *exitError
		if !errors.As(err, &exit) || len(stdout) == 0 {
			return nil, fmt.Errorf("trivy failed: %w", err)
		}
	}
	return parseTrivyOutput(stdout)
}

// parseTrivyOutput parses Trivy JSON output into findings
func parseTrivyOutput(data []byte) ([]Finding, error) {
	var report TrivyReport
	if err := json.Unmarshal(data, &report); err != nil {
		return nil, fmt.Errorf("failed to parse trivy output: %w", err)
	}

	var findings []Finding

	for _, result := range report.Results {
		// Process vulnerabilities
		for _, vuln := range result.Vulnerabilities {
			// Build references from PrimaryURL and advisory links
			refs := make([]string, 0, len(vuln.References)+1)
			if vuln.PrimaryURL != "" {
				refs = append(refs, vuln.PrimaryURL)
			}
			for _, r := range vuln.References {
				if r != vuln.PrimaryURL {
					refs = append(refs, r)
				}
			}

			// Build a fix command suggestion when a fixed version is known
			fixCmd := ""
			if vuln.FixedVersion != "" {
				fixCmd = fmt.Sprintf("Update %s to %s", vuln.PkgName, vuln.FixedVersion)
			}

			findings = append(findings, Finding{
				ID:          vuln.VulnerabilityID,
				Title:       vuln.Title,
				Description: vuln.Description,
				Severity:    parseSeverity(vuln.Severity),
				Source:      "trivy",
				File:        result.Target,
				PkgName:     vuln.PkgName,
				Version:     vuln.InstalledVersion,
				FixedIn:     vuln.FixedVersion,
				References:  refs,
				FixCommand:  fixCmd,
			})
		}

		// Process secrets found by Trivy.
		//
		// The report has carried these since TrivySecret was declared; nothing
		// read them, so a secret Trivy found was parsed and dropped. Only the
		// secret stage asks for them (--scanners secret), so there is no risk of
		// the vulnerability stage returning the same finding twice.
		for _, secret := range result.Secrets {
			findings = append(findings, Finding{
				ID:          secret.RuleID,
				Title:       secret.Title,
				Description: secret.Category,
				Severity:    parseSeverity(secret.Severity),
				Source:      SourceTrivySecret,
				File:        result.Target,
				Line:        secret.StartLine,
				Match:       maskSecret(secret.Match),
			})
		}

		// Process licenses found by Trivy
		for _, license := range result.Licenses {
			findings = append(findings, Finding{
				ID:          license.Name,
				Title:       fmt.Sprintf("%s (%s)", license.PkgName, license.Name),
				Description: fmt.Sprintf("License category: %s", license.Category),
				Severity:    parseSeverity(license.Severity),
				Source:      "trivy-license",
				File:        license.FilePath,
				PkgName:     license.PkgName,
			})
		}

		// Process misconfigurations found by Trivy
		for _, misconf := range result.Misconfigurations {
			var miscRefs []string
			if misconf.PrimaryURL != "" {
				miscRefs = append(miscRefs, misconf.PrimaryURL)
			}
			findings = append(findings, Finding{
				ID:          misconf.AVDID,
				Title:       misconf.Title,
				Description: misconf.Desc,
				Severity:    parseSeverity(misconf.Severity),
				Source:      "trivy-misconfig",
				File:        result.Target,
				Line:        misconf.CauseMetadata.StartLine,
				Resolution:  misconf.Resolution,
				References:  miscRefs,
			})
		}
	}

	return findings, nil
}

// parseSeverity converts string severity to SeverityLevel
func parseSeverity(s string) SeverityLevel {
	switch strings.ToUpper(s) {
	case "CRITICAL":
		return SeverityCritical
	case "HIGH":
		return SeverityHigh
	case "MEDIUM":
		return SeverityMedium
	case "LOW":
		return SeverityLow
	default:
		return SeverityUnknown
	}
}

// maskSecret partially masks secret values for display
func maskSecret(s string) string {
	if len(s) <= 8 {
		return "****"
	}
	return s[:4] + "****" + s[len(s)-4:]
}

// GetTrivyCommand returns the command that would be executed, for display and
// logging. It is built by the same builder as the executed command, so the two
// cannot drift apart.
func GetTrivyCommand(target string, targetType TargetType, licenseMode bool, tool ToolSpec, server string, ignoreUnfixed bool, ignoreEOL bool) string {
	tc, err := trivyArgs(target, targetType, licenseMode, tool, server, ignoreUnfixed, ignoreEOL)
	if err != nil {
		return ""
	}
	return tc.String()
}

// GetTrivySecretCommand returns the secret scan command for display.
func GetTrivySecretCommand(target string, targetType TargetType, tool ToolSpec, server string) string {
	tc, err := trivySecretArgs(target, targetType, tool, server)
	if err != nil {
		return ""
	}
	return tc.String()
}

// RunTrivySecret executes Trivy with --scanners secret and returns findings.
// progressFn is an optional callback called with each stderr line.
func RunTrivySecret(ctx context.Context, target string, targetType TargetType, tool ToolSpec, server string, progressFn func(string)) ([]Finding, error) {
	tc, err := trivySecretArgs(target, targetType, tool, server)
	if err != nil {
		return nil, err
	}
	return runTrivy(ctx, tc, progressFn)
}

// GetTrivyMisconfigCommand returns the misconfiguration scan command for display.
func GetTrivyMisconfigCommand(target string, targetType TargetType, tool ToolSpec, server string, ignoreEOL bool) string {
	tc, err := trivyMisconfigArgs(target, targetType, tool, server, ignoreEOL)
	if err != nil {
		return ""
	}
	return tc.String()
}

// RunTrivyMisconfig executes Trivy with --scanners misconfig and returns findings.
// progressFn is an optional callback called with each stderr line.
func RunTrivyMisconfig(ctx context.Context, target string, targetType TargetType, tool ToolSpec, server string, ignoreEOL bool, progressFn func(string)) ([]Finding, error) {
	tc, err := trivyMisconfigArgs(target, targetType, tool, server, ignoreEOL)
	if err != nil {
		return nil, err
	}
	return runTrivy(ctx, tc, progressFn)
}

package scan

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"fmt"
	"os/exec"
	"strings"
)

// toolCmd is one subprocess invocation: the binary and the arguments handed to
// it. Building it is pure, which is what makes the argument surface — the part
// that decides what a scanner is actually asked to do — testable without a
// scanner installed.
//
// It is also what the UI displays. Deriving the shown command and the executed
// one from the same value is the point: the two used to be built separately and
// had drifted (§1.3 D19).
type toolCmd struct {
	Name string
	Args []string
	// Env is the child's whole environment when it is not nil, os.Environ()
	// plus what the caller added. It exists so a credential can reach a tool
	// without going through argv, which is readable from the process list —
	// the arrangement the clone already uses for http.extraHeader (§3.16).
	//
	// String() never renders it: the invocation is logged and shown in the UI.
	Env []string

	// Dir is the working directory the tool runs in, when it has one.
	//
	// It exists for plumber, whose `analyze` takes **no path argument**: it
	// works on the current directory. Without this the tool ran in whatever
	// directory DevDesk was launched from and reported
	// `--project is required (could not auto-detect from git remote)` — a
	// failure about a repository nobody had asked it to look at. Trivy and
	// Gitleaks take their target in argv and set nothing here.
	Dir string
}

// String renders the invocation as a shell command line, for logs and for the
// command the UI shows next to a scan.
func (c toolCmd) String() string {
	if c.Name == "" {
		return ""
	}
	line := strings.Join(append([]string{c.Name}, c.Args...), " ")
	// The directory is part of what the command means when the tool takes no
	// path: a logged invocation that cannot be re-run says less than it looks
	// like it does.
	if c.Dir != "" {
		return "cd " + c.Dir + " && " + line
	}
	return line
}

// exitError reports a tool that ran and exited non-zero. The code matters:
// both scanners use a non-zero exit to mean "I found something" rather than
// "I failed" — trivy for vulnerabilities, gitleaks for secrets — so callers
// have to tell the two apart.
type exitError struct {
	Code   int
	Stderr string
}

func (e *exitError) Error() string {
	if e.Stderr != "" {
		return fmt.Sprintf("exit status %d: %s", e.Code, strings.TrimSpace(e.Stderr))
	}
	return fmt.Sprintf("exit status %d", e.Code)
}

// commandRunner is the seam every subprocess in this package passes through.
//
// The package drives trivy and gitleaks as external processes, which makes it
// untestable without both installed and a repository to point them at. Routing
// through this interface lets tests exercise the argument building, the
// exit-code handling and the output parsing — where the defects live — against
// canned output.
type commandRunner interface {
	// Run executes tc and returns what it wrote to stdout. Lines written to
	// stderr are forwarded to progressFn as they arrive, which is how Trivy
	// reports its database download. A tool that runs and exits non-zero
	// returns its stdout along with an *exitError.
	Run(ctx context.Context, tc toolCmd, progressFn func(string)) ([]byte, error)
}

// cliRunner is the production commandRunner: it shells out to the real tools.
type cliRunner struct{}

func (cliRunner) Run(ctx context.Context, tc toolCmd, progressFn func(string)) ([]byte, error) {
	cmd := exec.CommandContext(ctx, tc.Name, tc.Args...) //nolint:gosec // name is one of trivy/gitleaks/plumber/docker
	cmd.Env = tc.Env                                     // nil inherits this process's environment, which is the default
	cmd.Dir = tc.Dir                                     // empty runs in DevDesk's own working directory

	var stdout bytes.Buffer
	cmd.Stdout = &stdout

	// Stderr is consumed two ways: streamed to progressFn while the tool runs,
	// and kept so a failure can be reported with the tool's own diagnostic.
	var stderr bytes.Buffer
	if progressFn != nil {
		pipe, err := cmd.StderrPipe()
		if err == nil {
			done := make(chan struct{})
			go func() {
				defer close(done)
				sc := bufio.NewScanner(pipe)
				for sc.Scan() {
					line := strings.TrimSpace(sc.Text())
					if line == "" {
						continue
					}
					stderr.WriteString(line)
					stderr.WriteByte('\n')
					progressFn(line)
				}
				// A read failure on the progress pipe is not a scan failure:
				// the report comes back on stdout, and the tool's exit code
				// says whether it succeeded. Dropping the rest of the progress
				// is the whole consequence.
				_ = sc.Err()
			}()
			if err := cmd.Start(); err != nil {
				return nil, fmt.Errorf("%s failed to start: %w", tc.Name, err)
			}
			<-done // drain stderr before Wait closes the pipe
			return finish(tc.Name, cmd, &stdout, &stderr)
		}
	}

	cmd.Stderr = &stderr
	if err := cmd.Start(); err != nil {
		return nil, fmt.Errorf("%s failed to start: %w", tc.Name, err)
	}
	return finish(tc.Name, cmd, &stdout, &stderr)
}

// finish waits for the tool and only then reads what it wrote.
//
// The order is the point, and it is not a style preference: os/exec fills the
// output buffers from goroutines it owns, and only Wait guarantees they are
// done. Reading the buffer in the same expression as Wait — which is what
// `return stdout.Bytes(), waitErr(..., cmd.Wait(), ...)` does, since operands
// are evaluated before the call — snapshots it while it is still empty, and
// every scan comes back with no findings.
func finish(name string, cmd *exec.Cmd, stdout, stderr *bytes.Buffer) ([]byte, error) {
	err := cmd.Wait()
	return stdout.Bytes(), waitErr(name, err, stderr.String())
}

// waitErr turns a non-zero exit into an *exitError carrying the code, and
// leaves anything else (a killed process, a broken pipe) as it is.
func waitErr(name string, err error, stderr string) error {
	if err == nil {
		return nil
	}
	var exitErr *exec.ExitError
	if errors.As(err, &exitErr) {
		if stderr == "" {
			stderr = string(exitErr.Stderr)
		}
		return &exitError{Code: exitErr.ExitCode(), Stderr: stderr}
	}
	return fmt.Errorf("%s failed: %w", name, err)
}

// runner is swapped by tests. Production code never reassigns it, so the
// package stays safe to call concurrently; tests that swap it must not run in
// parallel.
var runner commandRunner = cliRunner{}

